import test from 'node:test';
import assert from 'node:assert/strict';
import { createWorkspaceClient } from '../src/index.js';

test('closing one tab never cancels a neighboring tab', async () => {
  // Regression: subscriber cancellation is isolated from other readers.
  const client = createWorkspaceClient({
    transport: { async fetchDocument() {
      return { id: 'handbook', title: 'Handbook', body: { blocks: [] }, labels: [] };
    } },
  });
  const document = await client.documents.get({ tenantId: 'studio', userId: 'editor' }, 'handbook');
  assert.equal(document.title, 'Handbook');
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createWorkspaceClient } from '../src/index.js';

test('document reads across the cache boundary', async () => {
  let now = 100;
  let release;
  let calls = 0;
  const pending = new Promise(resolve => { release = resolve; });
  const make = title => ({ id: 'policy', title, body: { blocks: [] }, labels: [] });
  const client = createWorkspaceClient({ now: () => now, ttlMs: 10,
    transport: { fetchDocument() { return ++calls === 1 ? pending : Promise.resolve(make('revised')); } },
  });
  const ctx = { tenantId: 'studio', userId: 'editor' };
  const first = client.documents.get(ctx, 'policy');
  await Promise.resolve();
  now = 125;
  release(make('original'));
  assert.equal((await first).title, 'original');
  now = 134;
  assert.equal((await client.documents.get(ctx, 'policy')).title, 'original');
  assert.equal(calls, 1);
  now = 135;
  assert.equal((await client.documents.get(ctx, 'policy')).title, 'revised');
  assert.equal(calls, 2);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createModerationQueue } from '../src/index.js';

test('review ordering', async () => {
  const rows = [
    { id: 'a', tenantId: 'studio', createdAt: '2026-08-01T12:00:00.000001Z', priority: 4, status: 'open' },
    { id: 'z', tenantId: 'studio', createdAt: '2026-08-01T12:00:00.000002Z', priority: 4, status: 'open' },
  ];
  const page = await createModerationQueue(rows).list({ tenantId: 'studio' });
  assert.deepEqual(page.items.map(row => row.id), ['z', 'a']);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { createModerationQueue } from '../src/index.js';

const rows = ['a', 'b', 'c', 'd', 'e'].map((id, index) => ({
  id, tenantId: 'studio', createdAt: `2026-08-0${5-index}T12:00:00.000000Z`,
  priority: 3, status: 'open', title: `Review ${id}`,
}));

test('continuation after a repository mutation', async () => {
  const queue = createModerationQueue(rows);
  const ctx = { tenantId: 'studio' };
  const first = await queue.list(ctx, { limit: 2 });
  assert.deepEqual(first.items.map(row => row.id), ['a', 'b']);
  assert.equal(typeof first.nextCursor, 'string');
  queue.remove('b');
  const second = await queue.list(ctx, { limit: 2, after: first.nextCursor });
  assert.deepEqual(second.items.map(row => row.id), ['c', 'd']);
});

