import test from 'node:test';
import assert from 'node:assert/strict';
import { createModerationQueue } from '../src/index.js';

for (const limit of [1, 2, 5, 10, 20, 30, 40, 50]) {
  test(`empty queue at limit ${limit}`, async () => {
    const queue = createModerationQueue([]);
    assert.deepEqual(await queue.list({ tenantId: 'studio' }, { limit }), {
      items: [], nextCursor: null, previousCursor: null,
    });
  });
}
for (const status of ['open', 'closed', 'snoozed']) {
  test(`summary includes ${status}`, async () => {
    const queue = createModerationQueue([{ id: 'r1', tenantId: 'studio',
      createdAt: '2026-08-01T12:00:00.000000Z', priority: 3, status }]);
    assert.equal((await queue.summary({ tenantId: 'studio' }))[status], 1);
  });
}
test('rejects an empty status filter', async () => {
  await assert.rejects(createModerationQueue([]).list({ tenantId: 'studio' }, { statuses: [] }),
    { code: 'INVALID_QUERY' });
});

