import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { createWorkspaceClient } from '../src/index.js';

describe('workspace views', () => {
  it('loads a tab and its card', async () => {
    let finish;
    let calls = 0;
    const pending = new Promise(resolve => { finish = resolve; });
    const client = createWorkspaceClient({ transport: {
      fetchDocument() { calls += 1; return pending; },
    } });
    const ctx = { tenantId: 'studio', userId: 'editor' };
    const tab = client.documents.get(ctx, 'release', { locale: 'fr' });
    const card = client.previews.get(ctx, 'release', { locale: 'fr' });
    await Promise.resolve();
    assert.equal(calls, 1);
    finish({ id: 'release', title: 'Release', body: { blocks: [{ text: 'Notes' }] }, labels: ['team'] });
    const [document, preview] = await Promise.all([tab, card]);
    assert.equal(document.body.blocks[0].text, 'Notes');
    assert.deepEqual(preview, { id: 'release', title: 'Release', excerpt: 'Notes', labels: ['team'] });
    assert.equal(calls, 1);
  });
});

