import test from 'node:test';
import assert from 'node:assert/strict';
import { createModerationQueue } from '../src/index.js';

test('cursor protocol validation', async () => {
  const rows = ['a', 'b'].map((id, i) => ({ id, tenantId: 'studio',
    createdAt: `2026-08-0${2-i}T12:00:00.000000Z`, priority: 1, status: 'open' }));
  const queue = createModerationQueue(rows);
  const ctx = { tenantId: 'studio' };
  const first = await queue.list(ctx, { limit: 1 });
  assert.equal(typeof first.nextCursor, 'string');
  const envelope = JSON.parse(Buffer.from(first.nextCursor, 'base64url').toString('utf8'));
  envelope.version = 42;
  const token = Buffer.from(JSON.stringify(envelope)).toString('base64url');
  await assert.rejects(queue.list(ctx, { after: token }), { code: 'INVALID_CURSOR' });
});

import { test, expect, vi } from 'vitest';
import { createWorkspaceClient } from '../src/index.js';

test('two readers and one cancellation', async () => {
  const controller = new AbortController();
  const ctx = { tenantId: 'studio', userId: 'editor' };
  const value = { id: 'guide', title: 'Guide' };
  const client = { documents: { get: vi.fn().mockResolvedValue(value) } };
  const first = client.documents.get(ctx, 'guide', { signal: controller.signal });
  const second = client.documents.get(ctx, 'guide');
  controller.abort();
  await Promise.all([first, second]);
  expect(client.documents.get).toHaveBeenCalledTimes(2);
  expect(client.documents.get).toHaveBeenCalledWith(ctx, 'guide', { signal: controller.signal });
});

import test from 'node:test';
import { createWorkspaceClient } from '../src/index.js';
import { checkRecovery } from './support/recovery.js';

test('document recovery', async () => {
  await checkRecovery(createWorkspaceClient);
});

import assert from 'node:assert/strict';

export async function checkRecovery(createClient) {
  let requests = 0;
  const client = createClient({ transport: { async fetchDocument() {
    if (++requests === 1) throw Object.assign(new Error('Temporary'), { status: 503 });
    return { id: 'guide', title: 'Recovered', body: { blocks: [] }, labels: [] };
  } } });
  const ctx = { tenantId: 'studio', userId: 'reader' };
  await assert.rejects(client.documents.get(ctx, 'guide'), { status: 503 });
  const result = await client.documents.get(ctx, 'guide');
  assert.equal(result.title, 'Recovered');
  assert.equal(requests, 2);
}

